window.AUTH=window.AUTH||{};window.AUTH["06-1005"]={"d":"06-1005","id":"2007/06-1005","n":"United States v. Santos","src":["osg"],"briefs":[{"k":"reply","label":"Reply brief for the United States","date":"","url":"https://www.justice.gov/osg/media/200646/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/united-states-v-santos-reply-merits","n":57},{"k":"petitioner","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/213116/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/united-states-v-santos-brief-merits","n":104}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep553/usrep553507/usrep553507.pdf","tr":true,"items":[{"t":"case","label":"Arthur Andersen LLP v. United States","cite":"544 U.S. 696","y":2005,"id":"2004/04-368","sc":1,"sum":"The Court held that the jury instructions failed to convey that the federal document law required a \"consciousness of wrongdoing\" for conviction. There was nothing inherently corrupt in ordering employees to destroy documents, even if the aim was to keep the documents from the government.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"op":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"9"}},{"t":"case","label":"Crandon v. United States","cite":"494 U.S. 152","y":1990,"id":"1989/88-931","sc":1,"sum":"Section 209(a) does not apply to a severance payment that is made to encourage the payee to accept Government employment, but is made before the payee becomes a Government employee.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Granfinaciera, S.A. v. Nordberg","cite":"492 U.S. 33","y":1989,"id":"1988/87-1716","sc":1,"sum":"The Court held that the Seventh Amendment protected the right to a trial by jury in all cases in which a legal right, as opposed to an equitable right, was at issue.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Holland v. United States","cite":"348 U.S. 121","y":1954,"id":"scdb/1954-015","sc":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 13"}},{"t":"case","label":"Muscarello v. United States","cite":"524 U.S. 125","y":1998,"id":"1997/96-1654","sc":1,"sum":"The Court held that the phrase \"carries a firearm\" applies to a person who knowingly possesses and conveys firearms in a vehicle, including in the locked glove compartment or trunk of a car, which the person accompanies.","sumSrc":"Oyez","by":{"0":"20","1":"13, 42"}},{"t":"case","label":"Pruitt v. State","cite":"557 N.E.2d 684","y":1990,"court":"Ind. Ct. App.","url":"https://www.courtlistener.com/c/N.E.2d/557/684/","by":{"0":"19"}},{"t":"case","label":"United States v. Arthur","cite":"2006 WL 2992865","y":2006,"court":"E.D. Wis. Oct. 18","by":{"0":"14"}},{"t":"case","label":"United States v. Awada","cite":"425 F.3d 522","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/425/522/","by":{"0":"9","1":"36"}},{"t":"case","label":"United States v. DeVegter","cite":"439 F.3d 1299","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/439/1299/","by":{"0":"12"}},{"t":"case","label":"United States v. Dote","cite":"150 F. Supp. 2d 935","y":2001,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/150/935/","by":{"0":"14"}},{"t":"case","label":"United States v. Febus","cite":"218 F.3d 784","y":2000,"url":"https://www.courtlistener.com/c/F.3d/218/784/","op":2,"ar":3,"sum":"Rejecting argument that the evidence was insufficient to convict Santos of money laundering “because his cash payments to the bolita’s collectors and winners were essential transactions of the illegal gambling business, and thus cannot also constitute transactions under the promotion provision of the money laundering statute”.","sumSrc":"brief:0","by":{"0":"8, 17","1":"4, 5, 23"}},{"t":"case","label":"United States v. Flores","cite":"454 F.3d 149","y":2006,"url":"https://www.courtlistener.com/c/F.3d/454/149/","by":{"0":"9"}},{"t":"case","label":"United States v. Garguilo","cite":"554 F.2d 59","y":1977,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/554/59/","by":{"0":"13"}},{"t":"case","label":"United States v. Genova","cite":"333 F.3d 750","y":2003,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/333/750/","by":{"0":"14","1":"15"}},{"t":"case","label":"United States v. Giraldi","cite":"86 F.3d 1368","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/86/1368/","by":{"0":"9"}},{"t":"case","label":"United States v. Glick","cite":"142 F.3d 520","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/142/520/","by":{"0":"12"}},{"t":"case","label":"United States v. Grasso","cite":"381 F.3d 160","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/381/160/","sum":"Noting that Congress “might just as readily have used the term ‘profits’”.","sumSrc":"brief:1","by":{"0":"10","1":"7, 21, 28, 33"}},{"t":"case","label":"United States v. Iacaboni","cite":"363 F.3d 1","y":2004,"url":"https://www.courtlistener.com/c/F.3d/363/1/","sum":"Upholding a money laundering prosecution based on payment of the expenses of an illegal gambling business.","sumSrc":"brief:1","by":{"0":"7","1":"7, 22, 23, 26, 39"}},{"t":"case","label":"United States v. Kayser","cite":"488 F.3d 1070","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/488/1070/","by":{"0":"12"}},{"t":"case","label":"United States v. Lizza Indus., Inc.","cite":"775 F.2d 492","y":1985,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/775/492/","by":{"0":"4"}},{"t":"case","label":"United States v. Masters","cite":"924 F.2d 1362","y":1991,"url":"https://www.courtlistener.com/c/F.2d/924/1362/","by":{"0":"6, 14","1":"15"}},{"t":"case","label":"United States v. Pena","cite":"268 F.3d 215","y":2001,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/268/215/","by":{"0":"15"}},{"t":"case","label":"United States v. Riley","cite":"78 F.3d 367","y":1996,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/78/367/","by":{"0":"4"}},{"t":"case","label":"United States v. Sapoznik","cite":"161 F.3d 1117","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/161/1117/","by":{"0":"12, 15"}},{"t":"case","label":"United States v. Simmons","cite":"154 F.3d 765","y":1998,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/154/765/","by":{"0":"4","1":"15"}},{"t":"case","label":"United States v. Warner","cite":"2000 WL 2363220","y":2007,"court":"7th Cir. Aug. 21","by":{"0":"11"}},{"t":"case","label":"United States v. Watts","cite":"519 U.S. 148","y":1997,"id":"1996/95-1906","sc":1,"sum":"In a 7-2 per curiam opinion, the Court held that a jury's verdict of acquittal does not prevent a sentencing court from considering a defendant's conduct underlying the acquitted charge, so long as that conduct has been proved by a preponderance of the evidence. Justices Antonin Scalia and Stephen G. Breyer concurred.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"United States v. Wert-Ruiz","cite":"228 F.3d 250","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/228/250/","by":{"0":"9"}},{"t":"case","label":"United States v. Wynn","cite":"61 F.3d 921","y":1995,"url":"https://www.courtlistener.com/c/F.3d/61/921/","by":{"0":"9"}},{"t":"case","label":"Withrow v. Williams","cite":"507 U.S. 680","y":1993,"id":"1992/91-1030","sc":1,"sum":"The Supreme Court held that the decision in Stone had been one of prudence rather than one of jurisdiction.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Yee v. Escondido","cite":"503 U.S. 591","y":1992,"url":"https://supreme.justia.com/cases/federal/us/503/591/","sc":1,"by":{"0":"17"}},{"t":"usc","label":"18 U.S.C. § 981","url":"https://www.law.cornell.edu/uscode/text/18/981","subs":["(a)(2)(A)","(a)(2)(B)","(a)(2)(C)","(a)(2)"],"stext":{"head":"§981. Civil forfeiture","paras":[[0,"(a)(1) The following property is subject to forfeiture to the United States:"],[1,"(A) Any property, real or personal, involved in a transaction or attempted transaction in violation of section 1956, 1957 or 1960 of this title, or any property traceable to such property."],[1,"(B) Any property, real or personal, within the jurisdiction of the United States, constituting, derived from, or traceable to, any proceeds obtained directly or indirectly from an offense against a foreign nation, or any property used to facilitate such an offense, if the offense—"],[2,"(i) involves trafficking in nuclear, chemical, biological, or radiological weapons technology or material, or the manufacture, importation, sale, or distribution of a controlled substance (as that term is defined for purposes of the Controlled Substances Act), or any other conduct described in section 1956(c)(7)(B);"],[2,"(ii) would be punishable within the jurisdiction of the foreign nation by death or imprisonment for a term exceeding 1 year; and"],[2,"(iii) would be punishable under the laws of the United States by imprisonment for a term exceeding 1 year, if the act or activity constituting the offense had occurred within the jurisdiction of the United States."],[1,"(C) Any property, real or personal, which constitutes or is derived from proceeds traceable to a violation of section 215, 471, 472, 473, 474, 476, 477, 478, 479, 480, 481, 485, 486, 487, 488, 501, 502, 510, 542, 545, 656, 657, 670, 842, 844, 1005, 1006, 1007, 1014, 1028, 1029, 1030, 1032, or 1344 of this title or any offense constituting \"specified unlawful activity\" (as defined in section 1956(c)(7) of this title), or a conspiracy to commit such offense."],[1,"(D) Any property, real or personal, which represents or is traceable to the gross receipts obtained, directly or indirectly, from a violation of—"],[2,"(i) section 666(a)(1) (relating to Federal program fraud);"],[2,"(ii) section 1001 (relating to fraud and false statements);"],[2,"(iii) section 1031 (relating to major fraud against the United States);"],[2,"(iv) section 1032 (relating to concealment of assets from conservator or receiver of insured financial institution);"],[2,"(v) section 1341 (relating to mail fraud); or"],[2,"(vi) section 1343 (relating to wire fraud),"],[1,"if such violation relates to the sale of assets acquired or held by the the 1 Federal Deposit Insurance Corporation, as conservator or receiver for a financial institution, or any other conservator for a financial institution appointed by the Office of the Comptroller of the Currency or the National Credit Union Administration, as conservator or liquidating agent for a financial institution."],[1,"(E) With respect to an offense listed in subsection (a)(1)(D) committed for the purpose of executing or attempting to execute any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent statements, pretenses, representations or promises, the gross receipts of such an offense shall include all property, real or personal, tangible or intangible, which thereby is obtained, directly or indirectly."],[1,"(F) Any property, real or personal, which represents or is traceable to the gross proceeds obtained, directly or indirectly, from a violation of—"],[2,"(i) section 511 (altering or removing motor vehicle identification numbers);"],[2,"(ii) section 553 (importing or exporting stolen motor vehicles);"],[2,"(iii) section 2119 (armed robbery of automobiles);"],[2,"(iv) section 2312 (transporting stolen motor vehicles in interstate commerce); or"],[2,"(v) section 2313 (possessing or selling a stolen motor vehicle that has moved in interstate commerce)."],[1,"(G) All assets, foreign or domestic—"],[2,"(i) of any individual, entity, or organization engaged in planning or perpetrating any any 1 Federal crime of terrorism (as defined in section 2332b(g)(5)) against the United States, citizens or residents of the United States, or their property, and all assets, foreign or domestic, affording any person a source of influence over any such entity or organization;"],[2,"(ii) acquired or maintained by any person with the intent and for the purpose of supporting, planning, conducting, or concealing any Federal crime of terrorism (as defined in section 2332b(g)(5) 2 against the United States, citizens or residents of the United States, or their property;"],[2,"(iii) derived from, involved in, or used or intended to be used to commit any Federal crime of terrorism (as defined in section 2332b(g)(5)) against the United States, citizens or residents of the United States, or their property; or"],[2,"(iv) of any individual, entity, or organization engaged in planning or perpetrating any act of international terrorism (as defined in section 2331) against any international organization (as defined in section 209 of the State Department Basic Authorities Act of 1956 (22 U.S.C. 4309(b)) or against any foreign Government.3 Where the property sought for forfeiture is located beyond the territorial boundaries of the United States, an act in furtherance of such planning or perpetration must have occurred within the jurisdiction of the United States."],[1,"(H) Any property, real or personal, involved in a violation or attempted violation, or which constitutes or is derived from proceeds traceable to a violation, of section 2339C of this title."],[1,"(I) Any property, real or personal, that is involved in a violation or attempted violation, or which constitutes or is derived from proceeds traceable to a prohibition imposed pursuant to section 104(a) of the North Korea Sanctions and Policy Enhancement Act of 2016."],[0,"(2) For purposes of paragraph (1), the term \"proceeds\" is defined as follows:"],[1,"(A) In cases involving illegal goods, illegal services, unlawful activities, and telemarketing and health care fraud schemes, the term \"proceeds\" means property of any kind obtained directly or indirectly, as the result of the commission of the offense giving rise to forfeiture, and any property traceable thereto, and is not limited to the net gain or profit realized from the offense."],[1,"(B) In cases involving lawful goods or lawful services that are sold or provided in an illegal manner, the term \"proceeds\" means the amount of money acquired through the illegal transactions resulting in the forfeiture, less the direct costs incurred in providing the goods or services. The claimant shall have the burden of proof with respect to the issue of direct costs. The direct costs shall not include any part of the overhead expenses of the entity providing the goods or services, or any part of the income taxes paid by the entity."],[1,"(C) In cases involving fraud in the process of obtaining a loan or extension of credit, the court shall allow the claimant a deduction from the forfeiture to the extent that the loan was repaid, or the debt was satisfied, without any financial loss to the victim."],[0,"(b)(1) Except as provided in section 985, any property subject to forfeiture to the United States under subsection (a) may be seized by the Attorney General and, in the case of property involved in a violation investigated by the Secretary of the Treasury or the United States Postal Service, the property may also be seized by the Secretary of the Treasury or the Postal Service, respectively."],[0,"(2) Seizures pursuant to this section shall be made pursuant to a warrant obtained in the same manner as provided for a search warrant under the Federal Rules of Criminal Procedure, except that a seizure may be made without a warrant if—"],[1,"(A) a complaint for forfeiture has been filed in the United States district court and the court issued an arrest warrant in rem pursuant to the Supplemental Rules for Certain Admiralty and Maritime Claims;"],[1,"(B) there is probable cause to believe that the property is subject to forfeiture and—"],[2,"(i) the seizure is made pursuant to a lawful arrest or search; or"],[2,"(ii) another exception to the Fourth Amendment warrant requirement would apply; or"],[1,"(C) the property was lawfully seized by a State or local law enforcement agency and transferred to a Federal agency."],[0,"(3) Notwithstanding the provisions of rule 41(a) 4 of the Federal Rules of Criminal Procedure, a seizure warrant may be issued pursuant to this subsection by a judicial officer in any district in which a forfeiture action against the property may be filed under section 1355(b) of title 28, and may be executed in any district in which the property is found, or transmitted to the central authority of any foreign state for service in accordance with any treaty or other international agreement. Any motion for the return of property seized under this section shall be filed in the district court in which the seizure warrant was issued or in the district court for the district in which the property was seized."],[0,"(4)(A) If any person is arrested or charged in a foreign country in connection with an offense that would give rise to the forfeiture of property in the United States under this section or under the Controlled Substances Act, the Attorney General may apply to any Federal judge or magistrate judge in the district in which the property is located for an ex parte order restraining the property subject to forfeiture for not more than 30 days, except that the time may be extended for good cause shown at a hearing conducted in the manner provided in rule 43(e) of the Federal Rules of Civil Procedure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/981?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§981. Civil forfeiture","tname":"Crimes and Criminal Procedure","by":{"0":"6, 7, 7","1":"18, 18, 18, 18"}},{"t":"usc","label":"18 U.S.C. § 982","url":"https://www.law.cornell.edu/uscode/text/18/982","subs":["(a)(2)(A)","(a)(8)","(a)(5)","(a)(1)","(a)(3)","(a)(2)","(a)(7)","(a)(6)","(a)(4)","(a)(6)(A)(ii)(I)","(a)(8)(B)"],"stext":{"head":"§982. Criminal forfeiture","paras":[[0,"(a)(1) The court, in imposing sentence on a person convicted of an offense in violation of section 1956, 1957, or 1960 of this title, shall order that the person forfeit to the United States any property, real or personal, involved in such offense, or any property traceable to such property."],[0,"(2) The court, in imposing sentence on a person convicted of a violation of, or a conspiracy to violate—"],[1,"(A) section 215, 656, 657, 1005, 1006, 1007, 1014, 1341, 1343, or 1344 of this title, affecting a financial institution, or"],[1,"(B) section 471, 472, 473, 474, 476, 477, 478, 479, 480, 481, 485, 486, 487, 488, 501, 502, 510, 542, 545, 555, 842, 844, 1028, 1029, or 1030 of this title,"],[0,"shall order that the person forfeit to the United States any property constituting, or derived from, proceeds the person obtained directly or indirectly, as the result of such violation."],[0,"(3) The court, in imposing a sentence on a person convicted of an offense under—"],[1,"(A) section 666(a)(1) (relating to Federal program fraud);"],[1,"(B) section 1001 (relating to fraud and false statements);"],[1,"(C) section 1031 (relating to major fraud against the United States);"],[1,"(D) section 1032 (relating to concealment of assets from conservator, receiver, or liquidating agent of insured financial institution);"],[1,"(E) section 1341 (relating to mail fraud); or"],[1,"(F) section 1343 (relating to wire fraud),"],[0,"involving the sale of assets acquired or held by the the 1 Federal Deposit Insurance Corporation, as conservator or receiver for a financial institution or any other conservator for a financial institution appointed by the Office of the Comptroller of the Currency, or the National Credit Union Administration, as conservator or liquidating agent for a financial institution, shall order that the person forfeit to the United States any property, real or personal, which represents or is traceable to the gross receipts obtained, directly or indirectly, as a result of such violation."],[0,"(4) With respect to an offense listed in subsection (a)(3) committed for the purpose of executing or attempting to execute any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent statements, pretenses, representations, or promises, the gross receipts of such an offense shall include any property, real or personal, tangible or intangible, which is obtained, directly or indirectly, as a result of such offense."],[0,"(5) The court, in imposing sentence on a person convicted of a violation or conspiracy to violate—"],[1,"(A) section 511 (altering or removing motor vehicle identification numbers);"],[1,"(B) section 553 (importing or exporting stolen motor vehicles);"],[1,"(C) section 2119 (armed robbery of automobiles);"],[1,"(D) section 2312 (transporting stolen motor vehicles in interstate commerce); or"],[1,"(E) section 2313 (possessing or selling a stolen motor vehicle that has moved in interstate commerce);"],[0,"shall order that the person forfeit to the United States any property, real or personal, which represents or is traceable to the gross proceeds obtained, directly or indirectly, as a result of such violation."],[0,"(6)(A) The court, in imposing sentence on a person convicted of a violation of, or conspiracy to violate, section 274(a), 274A(a)(1), or 274A(a)(2) of the Immigration and Nationality Act or section 555, 1425, 1426, 1427, 1541, 1542, 1543, 1544, or 1546 of this title, or a violation of, or conspiracy to violate, section 1028 of this title if committed in connection with passport or visa issuance or use, shall order that the person forfeit to the United States, regardless of any provision of State law—"],[1,"(i) any conveyance, including any vessel, vehicle, or aircraft used in the commission of the offense of which the person is convicted; and"],[1,"(ii) any property real or personal—"],[2,"(I) that constitutes, or is derived from or is traceable to the proceeds obtained directly or indirectly from the commission of the offense of which the person is convicted; or"],[2,"(II) that is used to facilitate, or is intended to be used to facilitate, the commission of the offense of which the person is convicted."],[0,"(B) The court, in imposing sentence on a person described in subparagraph (A), shall order that the person forfeit to the United States all property described in that subparagraph."],[0,"(7) The court, in imposing sentence on a person convicted of a Federal health care offense, shall order the person to forfeit property, real or personal, that constitutes or is derived, directly or indirectly, from gross proceeds traceable to the commission of the offense."],[0,"(8) The court, in sentencing a defendant convicted of an offense under section 1028, 1029, 1341, 1342, 1343, or 1344, or of a conspiracy to commit such an offense, if the offense involves telemarketing (as that term is defined in section 2325), shall order that the defendant forfeit to the United States any real or personal property—"],[1,"(A) used or intended to be used to commit, to facilitate, or to promote the commission of such offense; and"],[1,"(B) constituting, derived from, or traceable to the gross proceeds that the defendant obtained directly or indirectly as a result of the offense."],[0,"(b)(1) The forfeiture of property under this section, including any seizure and disposition of the property and any related judicial or administrative proceeding, shall be governed by the provisions of section 413 (other than subsection (d) of that section) of the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 853)."],[0,"(2) The substitution of assets provisions of subsection 413(p) shall not be used to order a defendant to forfeit assets in place of the actual property laundered where such defendant acted merely as an intermediary who handled but did not retain the property in the course of the money laundering offense unless the defendant, in committing the offense or offenses giving rise to the forfeiture, conducted three or more separate transactions involving a total of $100,000 or more in any twelve month period."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/982?type=usc&year=mostrecent&link-type=html"},"head":"§982. Criminal forfeiture","tname":"Crimes and Criminal Procedure","by":{"0":"6, 6, 6","1":"19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19, 19"}},{"t":"usc","label":"18 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/18/1202","subs":["(b)"],"by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 1955","url":"https://www.law.cornell.edu/uscode/text/18/1955","subs":["(b)(2)(ii)","(d)","(a)","(b)(1)"],"stext":{"head":"§1955. Prohibition of illegal gambling businesses","paras":[[0,"(a) Whoever conducts, finances, manages, supervises, directs, or owns all or part of an illegal gambling business shall be fined under this title or imprisoned not more than five years, or both."],[0,"(b) As used in this section—"],[1,"(1) \"illegal gambling business\" means a gambling business which—"],[2,"(i) is a violation of the law of a State or political subdivision in which it is conducted;"],[2,"(ii) involves five or more persons who conduct, finance, manage, supervise, direct, or own all or part of such business; and"],[2,"(iii) has been or remains in substantially continuous operation for a period in excess of thirty days or has a gross revenue of $2,000 in any single day."],[1,"(2) \"insured credit union\" shall have the meaning given the term in section 101 of the Federal Credit Union Act (12 U.S.C. 1752)."],[1,"(3) \"insured depository institution\" shall have the meaning given the term in section 3 of the Federal Deposit Insurance Act (12 U.S.C. 1813)."],[1,"(4) \"gambling\" includes but is not limited to pool-selling, bookmaking, maintaining slot machines, roulette wheels or dice tables, and conducting lotteries, policy, bolita or numbers games, or selling chances therein."],[1,"(5) \"savings promotion raffle\" means a contest in which the sole consideration required for a chance of winning designated prizes is obtained by the deposit of a specified amount of money in a savings account or other savings program, where each ticket or entry has an equal chance of being drawn, such contest being subject to regulations that may from time to time be promulgated by the appropriate prudential regulator (as defined in section 1002 of the Consumer Financial Protection Act of 2010 (12 U.S.C. 5481))."],[1,"(6) \"State\" means any State of the United States, the District of Columbia, the Commonwealth of Puerto Rico, and any territory or possession of the United States."],[0,"(c) If five or more persons conduct, finance, manage, supervise, direct, or own all or part of a gambling business and such business operates for two or more successive days, then, for the purpose of obtaining warrants for arrests, interceptions, and other searches and seizures, probable cause that the business receives gross revenue in excess of $2,000 in any single day shall be deemed to have been established."],[0,"(d) Any property, including money, used in violation of the provisions of this section may be seized and forfeited to the United States. All provisions of law relating to the seizures, summary, and judicial forfeiture procedures, and condemnation of vessels, vehicles, merchandise, and baggage for violation of the customs laws; the disposition of such vessels, vehicles, merchandise, and baggage or the proceeds from such sale; the remission or mitigation of such forfeitures; and the compromise of claims and the award of compensation to informers in respect of such forfeitures shall apply to seizures and forfeitures incurred or alleged to have been incurred under the provisions of this section, insofar as applicable and not inconsistent with such provisions. Such duties as are imposed upon the collector of customs or any other person in respect to the seizure and forfeiture of vessels, vehicles, merchandise, and baggage under the customs laws shall be performed with respect to seizures and forfeitures of property used or intended for use in violation of this section by such officers, agents, or other persons as may be designated for that purpose by the Attorney General."],[0,"(e) This section shall not apply to—"],[1,"(1) any bingo game, lottery, or similar game of chance conducted by an organization exempt from tax under paragraph (3) of subsection (c) of section 501 of the Internal Revenue Code of 1986, as amended, if no part of the gross receipts derived from such activity inures to the benefits of any private shareholder, member, or employee of such organization except as compensation for actual expenses incurred by him in the conduct of such activity; or"],[1,"(2) any savings promotion raffle."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1955?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1955. Prohibition of illegal gambling businesses","tname":"Crimes and Criminal Procedure","by":{"0":"18, 19, 18, 5","1":"3, 40, 25, 25"}},{"t":"usc","label":"18 U.S.C. § 1956","url":"https://www.law.cornell.edu/uscode/text/18/1956","subs":["(a)","(a)(1)","(a)(1)(A)(i)","(a)(1)(B)(i)","(a)(1)(A)(ii)","(a)(1)(B)(ii)","(a)(2)","(a)(3)","(c)(7)(A)","(h)"],"stext":{"head":"§1956. Laundering of monetary instruments","paras":[[0,"(a)(1) Whoever, knowing that the property involved in a financial transaction represents the proceeds of some form of unlawful activity, conducts or attempts to conduct such a financial transaction which in fact involves the proceeds of specified unlawful activity—"],[1,"(A)(i) with the intent to promote the carrying on of specified unlawful activity; or"],[1,"(ii) with intent to engage in conduct constituting a violation of section 7201 or 7206 of the Internal Revenue Code of 1986; or"],[1,"(B) knowing that the transaction is designed in whole or in part—"],[2,"(i) to conceal or disguise the nature, the location, the source, the ownership, or the control of the proceeds of specified unlawful activity; or"],[2,"(ii) to avoid a transaction reporting requirement under State or Federal law,"],[0,"shall be sentenced to a fine of not more than $500,000 or twice the value of the property involved in the transaction, whichever is greater, or imprisonment for not more than twenty years, or both. For purposes of this paragraph, a financial transaction shall be considered to be one involving the proceeds of specified unlawful activity if it is part of a set of parallel or dependent transactions, any one of which involves the proceeds of specified unlawful activity, and all of which are part of a single plan or arrangement."],[0,"(2) Whoever transports, transmits, or transfers, or attempts to transport, transmit, or transfer a monetary instrument or funds from a place in the United States to or through a place outside the United States or to a place in the United States from or through a place outside the United States—"],[1,"(A) with the intent to promote the carrying on of specified unlawful activity; or"],[1,"(B) knowing that the monetary instrument or funds involved in the transportation, transmission, or transfer represent the proceeds of some form of unlawful activity and knowing that such transportation, transmission, or transfer is designed in whole or in part—"],[2,"(i) to conceal or disguise the nature, the location, the source, the ownership, or the control of the proceeds of specified unlawful activity; or"],[2,"(ii) to avoid a transaction reporting requirement under State or Federal law,"],[0,"shall be sentenced to a fine of not more than $500,000 or twice the value of the monetary instrument or funds involved in the transportation, transmission, or transfer, whichever is greater, or imprisonment for not more than twenty years, or both. For the purpose of the offense described in subparagraph (B), the defendant's knowledge may be established by proof that a law enforcement officer represented the matter specified in subparagraph (B) as true, and the defendant's subsequent statements or actions indicate that the defendant believed such representations to be true."],[0,"(3) Whoever, with the intent—"],[1,"(A) to promote the carrying on of specified unlawful activity;"],[1,"(B) to conceal or disguise the nature, location, source, ownership, or control of property believed to be the proceeds of specified unlawful activity; or"],[1,"(C) to avoid a transaction reporting requirement under State or Federal law,"],[0,"conducts or attempts to conduct a financial transaction involving property represented to be the proceeds of specified unlawful activity, or property used to conduct or facilitate specified unlawful activity, shall be fined under this title or imprisoned for not more than 20 years, or both. For purposes of this paragraph and paragraph (2), the term \"represented\" means any representation made by a law enforcement officer or by another person at the direction of, or with the approval of, a Federal official authorized to investigate or prosecute violations of this section."],[0,"(b) Penalties.—"],[1,"(1) In general.—Whoever conducts or attempts to conduct a transaction described in subsection (a)(1) or (a)(3), or section 1957, or a transportation, transmission, or transfer described in subsection (a)(2), is liable to the United States for a civil penalty of not more than the greater of—"],[2,"(A) the value of the property, funds, or monetary instruments involved in the transaction; or"],[2,"(B) $10,000."],[1,"(2) Jurisdiction over foreign persons.—For purposes of adjudicating an action filed or enforcing a penalty ordered under this section, the district courts shall have jurisdiction over any foreign person, including any financial institution authorized under the laws of a foreign country, against whom the action is brought, if service of process upon the foreign person is made under the Federal Rules of Civil Procedure or the laws of the country in which the foreign person is found, and—"],[2,"(A) the foreign person commits an offense under subsection (a) involving a financial transaction that occurs in whole or in part in the United States;"],[2,"(B) the foreign person converts, to his or her own use, property in which the United States has an ownership interest by virtue of the entry of an order of forfeiture by a court of the United States; or"],[2,"(C) the foreign person is a financial institution that maintains a bank account at a financial institution in the United States."],[1,"(3) Court authority over assets.—A court may issue a pretrial restraining order or take any other action necessary to ensure that any bank account or other property held by the defendant in the United States is available to satisfy a judgment under this section."],[1,"(4) Federal receiver.—"],[2,"(A) In general.—A court may appoint a Federal Receiver, in accordance with subparagraph (B) of this paragraph, to collect, marshal, and take custody, control, and possession of all assets of the defendant, wherever located, to satisfy a civil judgment under this subsection, a forfeiture judgment under section 981 or 982, or a criminal sentence under section 1957 or subsection (a) of this section, including an order of restitution to any victim of a specified unlawful activity."],[2,"(B) Appointment and authority.—A Federal Receiver described in subparagraph (A)—"],[3,"(i) may be appointed upon application of a Federal prosecutor or a Federal or State regulator, by the court having jurisdiction over the defendant in the case;"],[3,"(ii) shall be an officer of the court, and the powers of the Federal Receiver shall include the powers set out in section 754 of title 28, United States Code; and"],[3,"(iii) shall have standing equivalent to that of a Federal prosecutor for the purpose of submitting requests to obtain information regarding the assets of the defendant—"],[4,"(I) from the Financial Crimes Enforcement Network of the Department of the Treasury; or"],[4,"(II) from a foreign country pursuant to a mutual legal assistance treaty, multilateral agreement, or other arrangement for international law enforcement assistance, provided that such requests are in accordance with the policies and procedures of the Attorney General."],[0,"(c) As used in this section—"],[1,"(1) the term \"knowing that the property involved in a financial transaction represents the proceeds of some form of unlawful activity\" means that the person knew the property involved in the transaction represented proceeds from some form, though not necessarily which form, of activity that constitutes a felony under State, Federal, or foreign law, regardless of whether or not such activity is specified in paragraph (7);"],[1,"(2) the term \"conducts\" includes initiating, concluding, or participating in initiating, or concluding a transaction;"],[1,"(3) the term \"transaction\" includes a purchase, sale, loan, pledge, gift, transfer, delivery, or other disposition, and with respect to a financial institution includes a deposit, withdrawal, transfer between accounts, exchange of currency, loan, extension of credit, purchase or sale of any stock, bond, certificate of deposit, or other monetary instrument, use of a safe deposit box, or any other payment, transfer, or delivery by, through, or to a financial institution, by whatever means effected;"],[1,"(4) the term \"financial transaction\" means (A) a transaction which in any way or degree affects interstate or foreign commerce (i) involving the movement of funds by wire or other means or (ii) involving one or more monetary instruments, or (iii) involving the transfer of title to any real property, vehicle, vessel, or aircraft, or (B) a transaction involving the use of a financial institution which is engaged in, or the activities of which affect, interstate or foreign commerce in any way or degree;"],[1,"(5) the term \"monetary instruments\" means (i) coin or currency of the United States or of any other country, travelers' checks, personal checks, bank checks, and money orders, or (ii) investment securities or negotiable instruments, in bearer form or otherwise in such form that title thereto passes upon delivery;"],[1,"(6) the term \"financial institution\" includes—"],[2,"(A) any financial institution, as defined in section 5312(a)(2) of title 31, United States Code, or the regulations promulgated thereunder; and"],[2,"(B) any foreign bank, as defined in section 1 of the International Banking Act of 1978 (12 U.S.C. 3101);"],[1,"(7) the term \"specified unlawful activity\" means—"],[2,"(A) any act or activity constituting an offense listed in section 1961(1) of this title except an act which is indictable under subchapter II of chapter 53 of title 31;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1956?type=usc&year=mostrecent&link-type=html"},"op":9,"head":"§1956. Laundering of monetary instruments","tname":"Crimes and Criminal Procedure","by":{"0":"16, 1, 9, 20, 20","1":"25, 25, 25, 25, 25, 25, 25, 26, 3, 26, 3, 26"}},{"t":"usc","label":"18 U.S.C. § 1963","url":"https://www.law.cornell.edu/uscode/text/18/1963","subs":["(a)","(a)(3)"],"stext":{"head":"§1963. Criminal penalties","paras":[[0,"(a) Whoever violates any provision of section 1962 of this chapter shall be fined under this title or imprisoned not more than 20 years (or for life if the violation is based on a racketeering activity for which the maximum penalty includes life imprisonment), or both, and shall forfeit to the United States, irrespective of any provision of State law—"],[1,"(1) any interest the person has acquired or maintained in violation of section 1962;"],[1,"(2) any—"],[2,"(A) interest in;"],[2,"(B) security of;"],[2,"(C) claim against; or"],[2,"(D) property or contractual right of any kind affording a source of influence over;"],[1,"any enterprise which the person has established, operated, controlled, conducted, or participated in the conduct of, in violation of section 1962; and"],[1,"(3) any property constituting, or derived from, any proceeds which the person obtained, directly or indirectly, from racketeering activity or unlawful debt collection in violation of section 1962."],[0,"The court, in imposing sentence on such person shall order, in addition to any other sentence imposed pursuant to this section, that the person forfeit to the United States all property described in this subsection. In lieu of a fine otherwise authorized by this section, a defendant who derives profits or other proceeds from an offense may be fined not more than twice the gross profits or other proceeds."],[0,"(b) Property subject to criminal forfeiture under this section includes—"],[1,"(1) real property, including things growing on, affixed to, and found in land; and"],[1,"(2) tangible and intangible personal property, including rights, privileges, interests, claims, and securities."],[0,"(c) All right, title, and interest in property described in subsection (a) vests in the United States upon the commission of the act giving rise to forfeiture under this section. Any such property that is subsequently transferred to a person other than the defendant may be the subject of a special verdict of forfeiture and thereafter shall be ordered forfeited to the United States, unless the transferee establishes in a hearing pursuant to subsection (l) that he is a bona fide purchaser for value of such property who at the time of purchase was reasonably without cause to believe that the property was subject to forfeiture under this section."],[0,"(d)(1) Upon application of the United States, the court may enter a restraining order or injunction, require the execution of a satisfactory performance bond, or take any other action to preserve the availability of property described in subsection (a) for forfeiture under this section—"],[1,"(A) upon the filing of an indictment or information charging a violation of section 1962 of this chapter and alleging that the property with respect to which the order is sought would, in the event of conviction, be subject to forfeiture under this section; or"],[1,"(B) prior to the filing of such an indictment or information, if, after notice to persons appearing to have an interest in the property and opportunity for a hearing, the court determines that—"],[2,"(i) there is a substantial probability that the United States will prevail on the issue of forfeiture and that failure to enter the order will result in the property being destroyed, removed from the jurisdiction of the court, or otherwise made unavailable for forfeiture; and"],[2,"(ii) the need to preserve the availability of the property through the entry of the requested order outweighs the hardship on any party against whom the order is to be entered:"],[0,"Provided, however, That an order entered pursuant to subparagraph (B) shall be effective for not more than ninety days, unless extended by the court for good cause shown or unless an indictment or information described in subparagraph (A) has been filed."],[0,"(2) A temporary restraining order under this subsection may be entered upon application of the United States without notice or opportunity for a hearing when an information or indictment has not yet been filed with respect to the property, if the United States demonstrates that there is probable cause to believe that the property with respect to which the order is sought would, in the event of conviction, be subject to forfeiture under this section and that provision of notice will jeopardize the availability of the property for forfeiture. Such a temporary order shall expire not more than fourteen days after the date on which it is entered, unless extended for good cause shown or unless the party against whom it is entered consents to an extension for a longer period. A hearing requested concerning an order entered under this paragraph shall be held at the earliest possible time, and prior to the expiration of the temporary order."],[0,"(3) The court may receive and consider, at a hearing held pursuant to this subsection, evidence and information that would be inadmissible under the Federal Rules of Evidence."],[0,"(e) Upon conviction of a person under this section, the court shall enter a judgment of forfeiture of the property to the United States and shall also authorize the Attorney General to seize all property ordered forfeited upon such terms and conditions as the court shall deem proper. Following the entry of an order declaring the property forfeited, the court may, upon application of the United States, enter such appropriate restraining orders or injunctions, require the execution of satisfactory performance bonds, appoint receivers, conservators, appraisers, accountants, or trustees, or take any other action to protect the interest of the United States in the property ordered forfeited. Any income accruing to, or derived from, an enterprise or an interest in an enterprise which has been ordered forfeited under this section may be used to offset ordinary and necessary expenses to the enterprise which are required by law, or which are necessary to protect the interests of the United States or third parties."],[0,"(f) Following the seizure of property ordered forfeited under this section, the Attorney General shall direct the disposition of the property by sale or any other commercially feasible means, making due provision for the rights of any innocent persons. Any property right or interest not exercisable by, or transferable for value to, the United States shall expire and shall not revert to the defendant, nor shall the defendant or any person acting in concert with or on behalf of the defendant be eligible to purchase forfeited property at any sale held by the United States. Upon application of a person, other than the defendant or a person acting in concert with or on behalf of the defendant, the court may restrain or stay the sale or disposition of the property pending the conclusion of any appeal of the criminal case giving rise to the forfeiture, if the applicant demonstrates that proceeding with the sale or disposition of the property will result in irreparable injury, harm or loss to him. Notwithstanding 31 U.S.C. 3302(b), the proceeds of any sale or other disposition of property forfeited under this section and any moneys forfeited shall be used to pay all proper expenses for the forfeiture and the sale, including expenses of seizure, maintenance and custody of the property pending its disposition, advertising and court costs. The Attorney General shall deposit in the Treasury any amounts of such proceeds or moneys remaining after the payment of such expenses."],[0,"(g) With respect to property ordered forfeited under this section, the Attorney General is authorized to—"],[1,"(1) grant petitions for mitigation or remission of forfeiture, restore forfeited property to victims of a violation of this chapter, or take any other action to protect the rights of innocent persons which is in the interest of justice and which is not inconsistent with the provisions of this chapter;"],[1,"(2) compromise claims arising under this section;"],[1,"(3) award compensation to persons providing information resulting in a forfeiture under this section;"],[1,"(4) direct the disposition by the United States of all property ordered forfeited under this section by public sale or any other commercially feasible means, making due provision for the rights of innocent persons; and"],[1,"(5) take appropriate measures necessary to safeguard and maintain property ordered forfeited under this section pending its disposition."],[0,"(h) The Attorney General may promulgate regulations with respect to—"],[1,"(1) making reasonable efforts to provide notice to persons who may have an interest in property ordered forfeited under this section;"],[1,"(2) granting petitions for remission or mitigation of forfeiture;"],[1,"(3) the restitution of property to victims of an offense petitioning for remission or mitigation of forfeiture under this chapter;"],[1,"(4) the disposition by the United States of forfeited property by public sale or other commercially feasible means;"],[1,"(5) the maintenance and safekeeping of any property forfeited under this section pending its disposition; and"],[1,"(6) the compromise of claims arising under this chapter."],[0,"Pending the promulgation of such regulations, all provisions of law relating to the disposition of property, or the proceeds from the sale thereof, or the remission or mitigation of forfeitures for violation of the customs laws, and the compromise of claims and the award of compensation to informers in respect of such forfeitures shall apply to forfeitures incurred, or alleged to have been incurred, under the provisions of this section, insofar as applicable and not inconsistent with the provisions hereof. Such duties as are imposed upon the Customs Service or any person with respect to the disposition of property under the customs law shall be performed under this chapter by the Attorney General."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1963?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1963. Criminal penalties","tname":"Crimes and Criminal Procedure","by":{"0":"5, 4","1":"10, 15, 10, 15"}},{"t":"usc","label":"18 U.S.C. § 2339C","url":"https://www.law.cornell.edu/uscode/text/18/2339C","subs":["(c)(2)","(e)(3)"],"stext":{"head":"§2339C. Prohibitions against the financing of terrorism","paras":[[0,"(a) Offenses.—"],[1,"(1) In general.—Whoever, in a circumstance described in subsection (b), by any means, directly or indirectly, unlawfully and willfully provides or collects funds with the intention that such funds be used, or with the knowledge that such funds are to be used, in full or in part, in order to carry out—"],[2,"(A) an act which constitutes an offense within the scope of a treaty specified in subsection (e)(7), as implemented by the United States, or"],[2,"(B) any other act intended to cause death or serious bodily injury to a civilian, or to any other person not taking an active part in the hostilities in a situation of armed conflict, when the purpose of such act, by its nature or context, is to intimidate a population, or to compel a government or an international organization to do or to abstain from doing any act,"],[1,"shall be punished as prescribed in subsection (d)(1)."],[1,"(2) Attempts and conspiracies.—Whoever attempts or conspires to commit an offense under paragraph (1) shall be punished as prescribed in subsection (d)(1)."],[1,"(3) Relationship to predicate act.—For an act to constitute an offense set forth in this subsection, it shall not be necessary that the funds were actually used to carry out a predicate act."],[0,"(b) Jurisdiction.—There is jurisdiction over the offenses in subsection (a) in the following circumstances—"],[1,"(1) the offense takes place in the United States and—"],[2,"(A) a perpetrator was a national of another state or a stateless person;"],[2,"(B) on board a vessel flying the flag of another state or an aircraft which is registered under the laws of another state at the time the offense is committed;"],[2,"(C) on board an aircraft which is operated by the government of another state;"],[2,"(D) a perpetrator is found outside the United States;"],[2,"(E) was directed toward or resulted in the carrying out of a predicate act against—"],[3,"(i) a national of another state; or"],[3,"(ii) another state or a government facility of such state, including its embassy or other diplomatic or consular premises of that state;"],[2,"(F) was directed toward or resulted in the carrying out of a predicate act committed in an attempt to compel another state or international organization to do or abstain from doing any act; or"],[2,"(G) was directed toward or resulted in the carrying out of a predicate act—"],[3,"(i) outside the United States; or"],[3,"(ii) within the United States, and either the offense or the predicate act was conducted in, or the results thereof affected, interstate or foreign commerce;"],[1,"(2) the offense takes place outside the United States and—"],[2,"(A) a perpetrator is a national of the United States or is a stateless person whose habitual residence is in the United States;"],[2,"(B) a perpetrator is found in the United States; or"],[2,"(C) was directed toward or resulted in the carrying out of a predicate act against—"],[3,"(i) any property that is owned, leased, or used by the United States or by any department or agency of the United States, including an embassy or other diplomatic or consular premises of the United States;"],[3,"(ii) any person or property within the United States;"],[3,"(iii) any national of the United States or the property of such national; or"],[3,"(iv) any property of any legal entity organized under the laws of the United States, including any of its States, districts, commonwealths, territories, or possessions;"],[1,"(3) the offense is committed on board a vessel flying the flag of the United States or an aircraft which is registered under the laws of the United States at the time the offense is committed;"],[1,"(4) the offense is committed on board an aircraft which is operated by the United States; or"],[1,"(5) the offense was directed toward or resulted in the carrying out of a predicate act committed in an attempt to compel the United States to do or abstain from doing any act."],[0,"(c) Concealment.—Whoever—"],[1,"(1)(A) is in the United States; or"],[1,"(B) is outside the United States and is a national of the United States or a legal entity organized under the laws of the United States (including any of its States, districts, commonwealths, territories, or possessions); and"],[1,"(2) knowingly conceals or disguises the nature, location, source, ownership, or control of any material support or resources, or any funds or proceeds of such funds—"],[2,"(A) knowing or intending that the support or resources are to be provided, or knowing that the support or resources were provided, in violation of section 2339B of this title; or"],[2,"(B) knowing or intending that any such funds are to be provided or collected, or knowing that the funds were provided or collected, in violation of subsection (a),"],[0,"shall be punished as prescribed in subsection (d)(2)."],[0,"(d) Penalties.—"],[1,"(1) Subsection (a).—Whoever violates subsection (a) shall be fined under this title, imprisoned for not more than 20 years, or both."],[1,"(2) Subsection (c).—Whoever violates subsection (c) shall be fined under this title, imprisoned for not more than 10 years, or both."],[0,"(e) Definitions.—In this section—"],[1,"(1) the term \"funds\" means assets of every kind, whether tangible or intangible, movable or immovable, however acquired, and legal documents or instruments in any form, including electronic or digital, evidencing title to, or interest in, such assets, including coin, currency, bank credits, travelers checks, bank checks, money orders, shares, securities, bonds, drafts, and letters of credit;"],[1,"(2) the term \"government facility\" means any permanent or temporary facility or conveyance that is used or occupied by representatives of a state, members of a government, the legislature, or the judiciary, or by officials or employees of a state or any other public authority or entity or by employees or officials of an intergovernmental organization in connection with their official duties;"],[1,"(3) the term \"proceeds\" means any funds derived from or obtained, directly or indirectly, through the commission of an offense set forth in subsection (a);"],[1,"(4) the term \"provides\" includes giving, donating, and transmitting;"],[1,"(5) the term \"collects\" includes raising and receiving;"],[1,"(6) the term \"predicate act\" means any act referred to in subparagraph (A) or (B) of subsection (a)(1);"],[1,"(7) the term \"treaty\" means—"],[2,"(A) the Convention for the Suppression of Unlawful Seizure of Aircraft, done at The Hague on December 16, 1970;"],[2,"(B) the Convention for the Suppression of Unlawful Acts against the Safety of Civil Aviation, done at Montreal on September 23, 1971;"],[2,"(C) the Convention on the Prevention and Punishment of Crimes against Internationally Protected Persons, including Diplomatic Agents, adopted by the General Assembly of the United Nations on December 14, 1973;"],[2,"(D) the International Convention against the Taking of Hostages, adopted by the General Assembly of the United Nations on December 17, 1979;"],[2,"(E) the Convention on the Physical Protection of Nuclear Material, adopted at Vienna on March 3, 1980;"],[2,"(F) the Protocol for the Suppression of Unlawful Acts of Violence at Airports Serving International Civil Aviation, supplementary to the Convention for the Suppression of Unlawful Acts against the Safety of Civil Aviation, done at Montreal on February 24, 1988;"],[2,"(G) the Convention for the Suppression of Unlawful Acts against the Safety of Maritime Navigation, done at Rome on March 10, 1988;"],[2,"(H) the Protocol for the Suppression of Unlawful Acts against the Safety of Fixed Platforms located on the Continental Shelf, done at Rome on March 10, 1988; or"],[2,"(I) the International Convention for the Suppression of Terrorist Bombings, adopted by the General Assembly of the United Nations on December 15, 1997;"],[1,"(8) the term \"intergovernmental organization\" includes international organizations;"],[1,"(9) the term \"international organization\" has the same meaning as in section 1116(b)(5) of this title;"],[1,"(10) the term \"armed conflict\" does not include internal disturbances and tensions, such as riots, isolated and sporadic acts of violence, and other acts of a similar nature;"],[1,"(11) the term \"serious bodily injury\" has the same meaning as in section 1365(g)(3) of this title; 1"],[1,"(12) the term \"national of the United States\" has the meaning given that term in section 101(a)(22) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(22));"],[1,"(13) the term \"material support or resources\" has the same meaning given that term in section 2339B(g)(4) of this title; and"],[1,"(14) the term \"state\" has the same meaning as that term has under international law, and includes all political subdivisions thereof."],[0,"(f) Civil Penalty.—In addition to any other criminal, civil, or administrative liability or penalty, any legal entity located within the United States or organized under the laws of the United States, including any of the laws of its States, districts, commonwealths, territories, or possessions, shall be liable to the United States for the sum of at least $10,000, if a person responsible for the management or control of that legal entity has, in that capacity, committed an offense set forth in subsection (a)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2339C?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2339C. Prohibitions against the financing of terrorism","tname":"Crimes and Criminal Procedure","by":{"0":"5, 5, 5, 6","1":"17, 17"}},{"t":"usc","label":"21 U.S.C. § 853","url":"https://www.law.cornell.edu/uscode/text/21/853","subs":["(a)","(a)(1)","(a)(2)"],"stext":{"head":"§853. Criminal forfeitures","paras":[[0,"(a) Property subject to criminal forfeiture"],[0,"Any person convicted of a violation of this subchapter or subchapter II punishable by imprisonment for more than one year shall forfeit to the United States, irrespective of any provision of State law—"],[1,"(1) any property constituting, or derived from, any proceeds the person obtained, directly or indirectly, as the result of such violation;"],[1,"(2) any of the person's property used, or intended to be used, in any manner or part, to commit, or to facilitate the commission of, such violation; and"],[1,"(3) in the case of a person convicted of engaging in a continuing criminal enterprise in violation of section 848 of this title, the person shall forfeit, in addition to any property described in paragraph (1) or (2), any of his interest in, claims against, and property or contractual rights affording a source of control over, the continuing criminal enterprise."],[0,"The court, in imposing sentence on such person, shall order, in addition to any other sentence imposed pursuant to this subchapter or subchapter II, that the person forfeit to the United States all property described in this subsection. In lieu of a fine otherwise authorized by this part, a defendant who derives profits or other proceeds from an offense may be fined not more than twice the gross profits or other proceeds."],[0,"(b) Meaning of term \"property\""],[0,"Property subject to criminal forfeiture under this section includes—"],[1,"(1) real property, including things growing on, affixed to, and found in land; and"],[1,"(2) tangible and intangible personal property, including rights, privileges, interests, claims, and securities."],[0,"(c) Third party transfers"],[0,"All right, title, and interest in property described in subsection (a) vests in the United States upon the commission of the act giving rise to forfeiture under this section. Any such property that is subsequently transferred to a person other than the defendant may be the subject of a special verdict of forfeiture and thereafter shall be ordered forfeited to the United States, unless the transferee establishes in a hearing pursuant to subsection (n) that he is a bona fide purchaser for value of such property who at the time of purchase was reasonably without cause to believe that the property was subject to forfeiture under this section."],[0,"(d) Rebuttable presumption"],[0,"There is a rebuttable presumption at trial that any property of a person convicted of a felony under this subchapter or subchapter II is subject to forfeiture under this section if the United States establishes by a preponderance of the evidence that—"],[1,"(1) such property was acquired by such person during the period of the violation of this subchapter or subchapter II or within a reasonable time after such period; and"],[1,"(2) there was no likely source for such property other than the violation of this subchapter or subchapter II."],[0,"(e) Protective orders"],[0,"(1) Upon application of the United States, the court may enter a restraining order or injunction, require the execution of a satisfactory performance bond, or take any other action to preserve the availability of property described in subsection (a) for forfeiture under this section—"],[1,"(A) upon the filing of an indictment or information charging a violation of this subchapter or subchapter II for which criminal forfeiture may be ordered under this section and alleging that the property with respect to which the order is sought would, in the event of conviction, be subject to forfeiture under this section; or"],[1,"(B) prior to the filing of such an indictment or information, if, after notice to persons appearing to have an interest in the property and opportunity for a hearing, the court determines that—"],[2,"(i) there is a substantial probability that the United States will prevail on the issue of forfeiture and that failure to enter the order will result in the property being destroyed, removed from the jurisdiction of the court, or otherwise made unavailable for forfeiture; and"],[2,"(ii) the need to preserve the availability of the property through the entry of the requested order outweighs the hardship on any party against whom the order is to be entered:"],[0,"Provided, however, That an order entered pursuant to subparagraph (B) shall be effective for not more than ninety days, unless extended by the court for good cause shown or unless an indictment or information described in subparagraph (A) has been filed."],[0,"(2) A temporary restraining order under this subsection may be entered upon application of the United States without notice or opportunity for a hearing when an information or indictment has not yet been filed with respect to the property, if the United States demonstrates that there is probable cause to believe that the property with respect to which the order is sought would, in the event of conviction, be subject to forfeiture under this section and that provision of notice will jeopardize the availability of the property for forfeiture. Such a temporary order shall expire not more than fourteen days after the date on which it is entered, unless extended for good cause shown or unless the party against whom it is entered consents to an extension for a longer period. A hearing requested concerning an order entered under this paragraph shall be held at the earliest possible time and prior to the expiration of the temporary order."],[0,"(3) The court may receive and consider, at a hearing held pursuant to this subsection, evidence and information that would be inadmissible under the Federal Rules of Evidence."],[0,"(4) Order to repatriate and deposit.—"],[1,"(A) In general.—Pursuant to its authority to enter a pretrial restraining order under this section, the court may order a defendant to repatriate any property that may be seized and forfeited, and to deposit that property pending trial in the registry of the court, or with the United States Marshals Service or the Secretary of the Treasury, in an interest-bearing account, if appropriate."],[1,"(B) Failure to comply.—Failure to comply with an order under this subsection, or an order to repatriate property under subsection (p), shall be punishable as a civil or criminal contempt of court, and may also result in an enhancement of the sentence of the defendant under the obstruction of justice provision of the Federal Sentencing Guidelines."],[0,"(f) Warrant of seizure"],[0,"The Government may request the issuance of a warrant authorizing the seizure of property subject to forfeiture under this section in the same manner as provided for a search warrant. If the court determines that there is probable cause to believe that the property to be seized would, in the event of conviction, be subject to forfeiture and that an order under subsection (e) may not be sufficient to assure the availability of the property for forfeiture, the court shall issue a warrant authorizing the seizure of such property."],[0,"(g) Execution"],[0,"Upon entry of an order of forfeiture under this section, the court shall authorize the Attorney General to seize all property ordered forfeited upon such terms and conditions as the court shall deem proper. Following entry of an order declaring the property forfeited, the court may, upon application of the United States, enter such appropriate restraining orders or injunctions, require the execution of satisfactory performance bonds, appoint receivers, conservators, appraisers, accountants, or trustees, or take any other action to protect the interest of the United States in the property ordered forfeited. Any income accruing to or derived from property ordered forfeited under this section may be used to offset ordinary and necessary expenses to the property which are required by law, or which are necessary to protect the interests of the United States or third parties."],[0,"(h) Disposition of property"],[0,"Following the seizure of property ordered forfeited under this section, the Attorney General shall direct the disposition of the property by sale or any other commercially feasible means, making due provision for the rights of any innocent persons. Any property right or interest not exercisable by, or transferable for value to, the United States shall expire and shall not revert to the defendant, nor shall the defendant or any person acting in concert with him or on his behalf be eligible to purchase forfeited property at any sale held by the United States. Upon application of a person, other than the defendant or a person acting in concert with him or on his behalf, the court may restrain or stay the sale or disposition of the property pending the conclusion of any appeal of the criminal case giving rise to the forfeiture, if the applicant demonstrates that proceeding with the sale or disposition of the property will result in irreparable injury, harm, or loss to him."],[0,"(i) Authority of the Attorney General"],[0,"With respect to property ordered forfeited under this section, the Attorney General is authorized to—"],[1,"(1) grant petitions for mitigation or remission of forfeiture, restore forfeited property to victims of a violation of this subchapter, or take any other action to protect the rights of innocent persons which is in the interest of justice and which is not inconsistent with the provisions of this section;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/853?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§853. Criminal forfeitures","tname":"Food and Drugs","by":{"0":"5, 4, 11","1":"10, 15, 16"}},{"t":"usc","label":"26 U.S.C. § 7203","url":"https://www.law.cornell.edu/uscode/text/26/7203","by":{"0":"12"}},{"t":"usc","label":"26 U.S.C. § 7206","url":"https://www.law.cornell.edu/uscode/text/26/7206","by":{"0":"12"}},{"t":"rule","label":"Fed. R. Evid. 1101","url":"https://www.law.cornell.edu/rules/fre/rule_1101","subs":["(d)(3)"],"by":{"0":"11, 12"}},{"t":"case","label":"Blockburger v. United States","cite":"284 U.S. 299","y":1932,"id":"scdb/1931-120","sc":1,"sum":"1. Two salesof morphine not in or from the original stamped package, the second having been initiated after the first was complete, held separate and distinct offenses under § 1 of the Narcotics Act, although buyer and seller were the same in both cases and but little time elapsed between the end of the one transaction and the beginning of the other.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"BP Am. Prod. Co. v. Burton","cite":"127 S. Ct. 638","y":2006,"id":"2006/05-669","sc":1,"sum":"The Court ruled 7-0 that \"the 6-year statute of limitations in 2415(a) applies only to court actions and not to the administrative proceedings involved in this case.\" The opinion by Justice Samuel Alito relied on the plain meaning of the language in Section 2415(a). The statute used the terms \"action\" and \"complaint\" when referring to the statute of limitations.","sumSrc":"Oyez","by":{"1":"13, 21"}},{"t":"case","label":"Burnet v. Sanford & Brooks Co.","cite":"282 U.S. 359","y":1931,"id":"scdb/1930-115","sc":1,"sum":"(1) That, under the Revenue Act of 1918, the money received in 1920 was properly included by the Commissioner as part of the gross income for that year in ascertaining the taxable income for that year. P. 363. (2) That a judgment in effect eliminating this money from the 1920 computation upon the condition that the taxpayer amend the earlier returns by omitting therefrom the deductions of related expenditures, was …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Callahan v. United States","cite":"364 U.S. 587","y":1961,"id":"1960/47","sc":1,"sum":"Under the Act, obstructing interstate commerce by extortion and conspiring to do so are separate offenses; separate consecutive sentences may be imposed for each offense. Pp. 587-597. 274 F. 2d 601, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"sum":"The Court held that Deal's second through sixth convictions in a single proceeding arose \"in the case of his second or subsequent conviction\" within the meaning of section 924(c)(1), finding that the statute was not ambiguous.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Limtiaco v. Camacho","cite":"127 S. Ct. 1413","y":2007,"id":"2006/06-116","sc":1,"sum":"The majority opinion by Justice Clarence Thomas held that, contrary to the Guam Supreme Court's interpretation, the phrase must mean the assessed value for tax purposes of property on Guam. \"The word 'tax' modifies 'valuation,' not 'property,'\" the Court reasoned, so \"tax valuation\" \"refers to the type of valuation to be conducted, not the object that is valued.\" The dissenting Justices argued that deciding the case on the basis of textual analysis and comparison to state debt limitations would amount to a \"coin toss.\" In the dissenters' view, Congress's purpose was to set a \"hard cap\" on debt, which would indicate that the debt limitation should be based on the full market (appraised) value of property on Guam rather than dependent on the changeable assessment rate.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Rutledge v. United States","cite":"517 U.S. 292","y":1996,"id":"1995/94-8769","sc":1,"sum":"Announced by Justice John Paul Stevens, the Court ruled one of the two sentences must be dropped. Both of the offenses were based on the same criminal act. Justice Stevens wrote, \"A guilty verdict on a (continuing criminal enterprise) charge necessarily includes a finding that the defendant also participated in a conspiracy.\".","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Smith v. United States","cite":"508 U.S. 223","y":1993,"id":"1992/91-8674","sc":1,"sum":"Authored by Justice Sandra Day O'Connor, the Court ruled that a criminal who trades his or her firearm for drugs \"uses\" it \"during and in relation to . . . [a] drug trafficking crime,\" which is within the bounds of the sentence enhancement. Justice O'Connor wrote that Congress intended to make the word \"use\" as broad as possible when it wrote the law.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Stinnett v. Iron Works Gym/Executive Health Spa, Inc.","cite":"301 F.3d 610","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/301/610/","by":{"1":"28"}},{"t":"case","label":"Thor Power Tool Co. v. Commissioner","cite":"439 U.S. 522","y":1979,"id":"1978/77-920","sc":1,"sum":"Inventory accounting for tax purposes is governed by §§ 446 and 471 of the Internal Revenue Code of 1954. Section 446 provides that taxable income is to be computed under the taxpayer's -normal method of accounting unless that method \"does not clearly reflect income,\" in which event taxable income is to be computed \"under such method as, in the opinion of the [Commissioner], does clearly reflect income.\" Section 471 …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33, 34"}},{"t":"case","label":"United States v. Alerre","cite":"430 F.3d 681","y":2005,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/430/681/","by":{"1":"23"}},{"t":"case","label":"United States v. Angelos","cite":"433 F.3d 738","y":2006,"url":"https://www.courtlistener.com/c/F.3d/433/738/","by":{"1":"23"}},{"t":"case","label":"United States v. Bolden","cite":"325 F.3d 471","y":2003,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/325/471/","by":{"1":"24"}},{"t":"case","label":"United States v. Butler","cite":"211 F.3d 826","y":2000,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/211/826/","by":{"1":"36"}},{"t":"case","label":"United States v. Caplinger","cite":"339 F.3d 226","y":2003,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/339/226/","by":{"1":"23"}},{"t":"case","label":"United States v. Casey","cite":"444 F.3d 1071","y":2006,"url":"https://www.courtlistener.com/c/F.3d/444/1071/","by":{"1":"16"}},{"t":"case","label":"United States v. Castellini","cite":"392 F.3d 35","y":2004,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/392/35/","by":{"1":"36"}},{"t":"case","label":"United States v. Conley","cite":"37 F.3d 970","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/37/970/","by":{"1":"24"}},{"t":"case","label":"United States v. DeFries","cite":"129 F.3d 1293","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/129/1293/","by":{"1":"15"}},{"t":"case","label":"United States v. Evans","cite":"272 F.3d 1069","y":2001,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/272/1069/","by":{"1":"24"}},{"t":"case","label":"United States v. France","cite":"164 F.3d 203","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/164/203/","by":{"1":"24"}},{"t":"case","label":"United States v. Heaps","cite":"39 F.3d 479","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/39/479/","by":{"1":"37"}},{"t":"case","label":"United States v. Hildebrand","cite":"152 F.3d 756","y":1998,"url":"https://www.courtlistener.com/c/F.3d/152/756/","by":{"1":"24"}},{"t":"case","label":"United States v. Huber","cite":"404 F.3d 1047","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/404/1047/","by":{"1":"8"}},{"t":"case","label":"United States v. Hurley","cite":"63 F.3d 1","y":1995,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/63/1/","sum":"Upholding a money laundering prosecution based on payment of the expenses of an illegal gambling business.","sumSrc":"brief:1","by":{"1":"15"}},{"t":"case","label":"United States v. Jackson","cite":"935 F.2d 832","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/935/832/","by":{"1":"16"}},{"t":"case","label":"United States v. Jeffers","cite":"532 F.2d 1101","y":1976,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/532/1101/","by":{"1":"16, 27"}},{"t":"case","label":"United States v. Johnson","cite":"297 F.3d 845","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/297/845/","by":{"1":"24"}},{"t":"case","label":"United States v. Johnson","cite":"971 F.2d 562","y":1992,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/971/562/","by":{"1":"37"}},{"t":"case","label":"United States v. Keeling","cite":"235 F.3d 533","y":2000,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/235/533/","by":{"1":"16"}},{"t":"case","label":"United States v. King","cite":"169 F.3d 1035","y":1999,"url":"https://www.courtlistener.com/c/F.3d/169/1035/","by":{"1":"24"}},{"t":"case","label":"United States v. Lawrence","cite":"405 F.3d 888","y":2005,"url":"https://www.courtlistener.com/c/F.3d/405/888/","by":{"1":"23"}},{"t":"case","label":"United States v. Mankarious","cite":"151 F.3d 694","y":1998,"url":"https://www.courtlistener.com/c/F.3d/151/694/","op":1,"by":{"1":"36, 37, 38, 39"}},{"t":"case","label":"United States v. Marbella","cite":"73 F.3d 1508","y":1996,"url":"https://www.courtlistener.com/c/F.3d/73/1508/","by":{"1":"24"}},{"t":"case","label":"United States v. McHan","cite":"101 F.3d 1027","y":1996,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/101/1027/","by":{"1":"17, 25, 28"}},{"t":"case","label":"United States v. Reed","cite":"167 F.3d 984","y":1999,"url":"https://www.courtlistener.com/c/F.3d/167/984/","by":{"1":"24"}},{"t":"case","label":"United States v. Rudisill","cite":"187 F.3d 1260","y":1999,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/187/1260/","by":{"1":"24"}},{"t":"case","label":"United States v. Scialabba","cite":"282 F.3d 475","y":2002,"url":"https://www.courtlistener.com/c/F.3d/282/475/","ar":2,"by":{"1":"passim"}},{"t":"case","label":"United States v. Silvestri","cite":"409 F.3d 1311","y":2005,"url":"https://www.courtlistener.com/c/F.3d/409/1311/","by":{"1":"17"}},{"t":"case","label":"United States v. Smith","cite":"31 F.3d 1294","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/31/1294/","by":{"1":"28"}},{"t":"case","label":"United States v. Thorn","cite":"446 F.3d 378","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/446/378/","by":{"1":"23"}},{"t":"case","label":"United States v. Wyly","cite":"193 F.3d 289","y":1999,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/193/289/","by":{"1":"24"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"1":"19"}},{"t":"usc","label":"18 U.S.C. § 1961","url":"https://www.law.cornell.edu/uscode/text/18/1961","subs":["(1)"],"by":{"1":"15, 21"}},{"t":"usc","label":"15 U.S.C. § 77s","url":"https://www.law.cornell.edu/uscode/text/15/77s","subs":["(b)"],"by":{"1":"33"}},{"t":"usc","label":"15 U.S.C. § 7218","url":"https://www.law.cornell.edu/uscode/text/15/7218","by":{"1":"33"}},{"t":"usc","label":"18 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/18/371","by":{"1":"3"}},{"t":"usc","label":"18 U.S.C. § 1957","url":"https://www.law.cornell.edu/uscode/text/18/1957","by":{"1":"17, 19, 26"}},{"t":"usc","label":"18 U.S.C. § 2318","url":"https://www.law.cornell.edu/uscode/text/18/2318","subs":["(f)(2)(C)(i)","(f)(3)(A)(ii)"],"by":{"1":"21, 21"}},{"t":"usc","label":"18 U.S.C. § 2520","url":"https://www.law.cornell.edu/uscode/text/18/2520","subs":["(c)(2)(A)"],"by":{"1":"20"}},{"t":"usc","label":"21 U.S.C. § 881","url":"https://www.law.cornell.edu/uscode/text/21/881","subs":["(a)(6)"],"by":{"1":"16"}},{"t":"usc","label":"26 U.S.C. § 162","url":"https://www.law.cornell.edu/uscode/text/26/162","subs":["(c)"],"by":{"1":"33"}},{"t":"usc","label":"26 U.S.C. § 280E","url":"https://www.law.cornell.edu/uscode/text/26/280E","by":{"1":"32, 34"}},{"t":"usc","label":"26 U.S.C. § 441","url":"https://www.law.cornell.edu/uscode/text/26/441","by":{"1":"33"}},{"t":"usc","label":"26 U.S.C. § 446","url":"https://www.law.cornell.edu/uscode/text/26/446","by":{"1":"33"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§2255. Federal custody; remedies on motion attacking sentence","tname":"Judiciary and Judicial Procedure","by":{"1":"6"}},{"t":"usc","label":"48 U.S.C. § 1423a","url":"https://www.law.cornell.edu/uscode/text/48/1423a","by":{"1":"20"}},{"t":"reg","label":"17 C.F.R. § 210.4-01","url":"https://www.ecfr.gov/current/title-17/section-210.4-01","subs":["(a)(1)"],"by":{"1":"33"}}]};